// Centralized blog data source — metadata only.
// Content lives in content/blog/<slug>.mdx (HTML body after frontmatter).
// To add a post: create the MDX file, add its slug to BLOG_SLUGS below.
// Generated by: node scripts/migrate-blog.mjs

import { readFileSync } from "node:fs";
import { join } from "node:path";
import matter from "gray-matter";

export interface BlogPost {
  slug: string;
  title: string;
  subtitle?: string;
  description: string;
  content: string;
  image: string;
  author: {
    name: string;
    avatar: string;
    bio: string;
    role: string;
    social: {
      twitter?: string;
      github?: string;
      linkedin?: string;
    };
  };
  date: string;
  readTime: string;
  tags: string[];
  featured?: boolean;
  seoKeywords: string[];
  lastModified?: string;
  /**
   * `archived: true` in frontmatter. The post still renders at /blog/<slug>
   * (its URL keeps returning 200 and stays in the sitemap) but it is excluded
   * from the blog index, the home page, the RSS feed and the tag lists, and
   * it renders with a "From the archive" note.
   *
   * Used for the 2024 batch: seventeen posts published 2024-09-28 to
   * 2024-10-09 that were written for search traffic, not to say anything.
   * Deleting them would break inbound links; leading with them would tell a
   * recruiter the wrong story about what the blog is for.
   */
  archived: boolean;
}

