// Posts that never had a real cover historically all point at this shared
// placeholder. Treat it (and an empty value) as "no cover" so we render a
// branded, per-post OG image instead of the same generic screenshot 24×.
const PLACEHOLDER_COVER = "/Images/portfolio1.png";

/** Branded per-post cover via the OG image generator (title + gradient). */
function generatedCover(title: string, description: string): string {
  const params = new URLSearchParams({ title, type: "blog" });
  if (description) params.set("description", description);
  return `/api/og?${params.toString()}`;
}

function loadPost(slug: string): BlogPost | null {
  try {
    const filePath = join(process.cwd(), "content", "blog", `${slug}.mdx`);
    const raw = readFileSync(filePath, "utf8");
    const { data, content } = matter(raw);
    const title = data.title ?? "";
    const description = data.description ?? "";
    const rawImage = data.image ?? "";
    const image =
      !rawImage || rawImage === PLACEHOLDER_COVER
        ? generatedCover(title || slug, description)
        : rawImage;
    return {
      slug,
      title,
      subtitle: data.subtitle,
      description,
      content,
      image,
      author: BLOG_AUTHOR,
      date: data.date ?? "",
      readTime: data.readTime ?? "",
      tags: data.tags ?? [],
      featured: data.featured ?? false,
      seoKeywords: data.seoKeywords ?? [],
      lastModified: data.lastModified,
      archived: data.archived === true,
    };
  } catch {
    return null;
  }
}

// Loaded once at module init — only runs server-side (fs usage is intentional).
/** Every post that renders — used by the sitemap and static params. */
export const blogPosts: BlogPost[] = BLOG_SLUGS.map(loadPost).filter(
  Boolean
) as BlogPost[];

/** Every post the site SURFACES — listing, home, feed, tags, related posts. */
export const publishedPosts: BlogPost[] = blogPosts.filter((p) => !p.archived);

export const getPostBySlug = (slug: string): BlogPost | undefined =>
  blogPosts.find((p) => p.slug === slug);

export const getRelatedPosts = (slug: string, limit = 3): BlogPost[] => {
  const post = getPostBySlug(slug);
  if (!post) return [];
  return publishedPosts
    .filter((p) => p.slug !== slug && p.tags.some((t) => post.tags.includes(t)))
    .slice(0, limit);
};

export const getFeaturedPosts = (): BlogPost[] =>
  publishedPosts.filter((p) => p.featured);

export const getAllTags = (): string[] => {
  const tags = new Set<string>();
  publishedPosts.forEach((p) => p.tags.forEach((t) => tags.add(t)));
  return Array.from(tags).sort((a, b) => a.localeCompare(b));
};

export const getPostsByTag = (tag: string): BlogPost[] =>
  publishedPosts.filter((p) => p.tags.includes(tag));
